"""Utilities for migrating ORD_LINE rows."""

from decimal import Decimal
from typing import Any


def _order_id(row: dict) -> str:
    value = row.get("ORD_ID", "")
    return "" if value is None else str(value)


def _line_sort_key(row: dict) -> tuple[int, Decimal]:
    value: Any = row.get("LINE_NO", "")
    if value is None or value == "":
        return (0, Decimal(0))
    return (1, Decimal(str(value).strip()))


def renumber(lines: list[dict]) -> list[dict]:
    """Remove deleted lines and renumber surviving lines independently per order."""
    grouped: dict[str, list[dict]] = {}

    for row in lines:
        if row.get("DEL_FLG", "") == "Y":
            continue
        grouped.setdefault(_order_id(row), []).append(row)

    result: list[dict] = []
    for order_id in sorted(grouped):
        rows = sorted(grouped[order_id], key=_line_sort_key)
        for line_no, row in enumerate(rows, start=1):
            new_row = dict(row)
            new_row["LINE_NO"] = line_no
            result.append(new_row)

    return result
